import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import http from 'node:http';
import { chromium } from 'playwright';
const core=await fs.readFile('shogi-v21528/tournament21541.js','utf8'),field=await fs.readFile('shogi-v21528/tournament-field21545.js','utf8'),boss=await fs.readFile('shogi-v21528/tournament-boss21546.js','utf8'),ui=await fs.readFile('shogi-v21528/tournament-ui21542.js','utf8'),bracketUI=await fs.readFile('shogi-v21528/tournament-ui21543.js','utf8'),skin=await fs.readFile('shogi-v21528/tournament-skin21544.js','utf8');
for(const m of ['pairingErrors','tourBracketLines','alignmentErrors',"version:'21543b'"])assert.ok(bracketUI.includes(m));assert.match(boss,/version:'21546a'/);
const names=['みつき','みっちゃん','あき王','おにまま','まま','ケンシロウ','ジャギ','しんじ','直江兼続','あやなみ','バット','伊達政宗','あすか','ユリア','玉ちゃん','まり','ぺんぺん','げんどー','前田慶次','シン','みさとさん','サウザー','リン','ラオウ','カヲル','未来からやってきたみつき'],ratings=[3000,2850,2700,2600,2500,2100,1450,1550,1700,1800,1600,1750,1900,1680,1380,1950,1250,2050,1820,2000,1880,2180,1500,2250,2400,3400],characters=names.map((name,i)=>({name,rating:ratings[i],fixed:true})),svg=i=>`data:image/svg+xml,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="40" height="40"><rect width="40" height="40" fill="white"/><text x="20" y="25" text-anchor="middle">${i}</text></svg>`)}`,cards=names.map((n,i)=>`<button class="ch"><img src="${svg(i)}" alt="${n}"><span class="chName">${n}</span></button>`).join('');
const html=`<!doctype html><meta charset="utf-8"><style>*{box-sizing:border-box}body{margin:0}.side{width:380px}.btn{padding:6px}</style><body><div class="side"><div class="controls"><button class="btn">new</button></div></div><div id="status"></div><div id="resultBanner"></div><div id="chars">${cards}</div><div id="board"></div><script>window.__mock={rating:1500,state:{log:[]},selected:[],characters:${JSON.stringify(characters)}};window.AIShogiIOS={characters:()=>window.__mock.characters,stats:()=>({rating:window.__mock.rating,w:0,l:0,d:0}),state:()=>window.__mock.state,select:i=>{window.__mock.selected.push(i);const b=document.getElementById('resultBanner');b.className='';return window.__mock.characters[i]}};</script><script src="/core.js"></script><script src="/field.js"></script><script src="/boss.js"></script><script src="/ui.js"></script><script src="/skin.js"></script></body>`;
const server=http.createServer((req,res)=>{const map={'/core.js':core,'/field.js':field,'/boss.js':boss,'/ui.js':ui,'/skin.js':skin};if(map[req.url]){res.writeHead(200,{'content-type':'application/javascript'});res.end(map[req.url]);return}if(req.url?.startsWith('/tournament-ui21543.js')){res.writeHead(200,{'content-type':'application/javascript'});res.end(bracketUI);return}res.writeHead(200,{'content-type':'text/html'});res.end(html)});await new Promise(r=>server.listen(43143,'127.0.0.1',r));const browser=await chromium.launch({headless:true});
try{const page=await browser.newPage({viewport:{width:1280,height:800}});await page.goto('http://127.0.0.1:43143/',{waitUntil:'load'});await page.waitForFunction(()=>window.AI_SHOGI_TOURNAMENT&&window.AI_SHOGI_TOURNAMENT_FIELD_RULE&&window.AI_SHOGI_TOURNAMENT_BOSS&&window.AI_SHOGI_TOURNAMENT_UI&&window.AI_SHOGI_TOURNAMENT_BRACKET_UI&&window.AI_SHOGI_TOURNAMENT_SKIN);await page.evaluate(()=>{window.AI_SHOGI_TOURNAMENT.start('mitsuki');document.getElementById('tournament21540Panel').classList.add('on');window.AI_SHOGI_TOURNAMENT.render();window.AI_SHOGI_TOURNAMENT_SKIN.refresh()});await page.waitForTimeout(300);assert.equal(await page.locator('.tourBracketRound[data-round="0"] .tourBracketSlot.boss').count(),0);assert.equal((await page.evaluate(()=>window.AI_SHOGI_TOURNAMENT_BOSS.audit())).bossInBracket,false);
 const openingSkin=await page.evaluate(()=>window.AI_SHOGI_TOURNAMENT_SKIN.audit());assert.equal(openingSkin.ok,true);assert.equal(openingSkin.connectors,30);assert.ok(openingSkin.alignmentError<=1.25);
 async function geometry(label){const g=await page.evaluate(()=>{const rs=[...document.querySelectorAll('.tourBracketRound')];let checks=0,max=0,errors=0;for(let r=0;r<4;r++){const src=[...rs[r].querySelectorAll('.tourBracketSlot')],dst=[...rs[r+1].querySelectorAll('.tourBracketSlot')];for(let i=0;i<dst.length;i++){const a=src[i*2],b=src[i*2+1],d=dst[i];if(!a||!b||!d)continue;const ar=a.getBoundingClientRect(),br=b.getBoundingClientRect(),dr=d.getBoundingClientRect(),e=Math.abs((((ar.top+ar.bottom)/2+(br.top+br.bottom)/2)/2)-((dr.top+dr.bottom)/2));checks++;max=Math.max(max,e);if(e>1.25)errors++}}return{checks,errors,max:Number(max.toFixed(3))}});assert.equal(g.checks,15,label);assert.equal(g.errors,0,label);assert.ok(g.max<=1.25);return g}
 async function win(){await page.evaluate(()=>{const b=document.getElementById('resultBanner');b.className='';void b.offsetWidth;b.className='on result-win'});await page.waitForTimeout(150)}async function roundAudit(r){const a=await page.evaluate(()=>window.AI_SHOGI_TOURNAMENT_BRACKET_UI.audit());assert.equal(a.pairingErrors,0);assert.equal(a.invalidWins,0);assert.equal(a.alignmentErrors,0);assert.ok(a.connectors>=30);await geometry('round '+r)}
 const opening=await geometry('opening');for(let r=0;r<4;r++){await win();await roundAudit(r);if(r<3){await page.waitForFunction(()=>window.AI_SHOGI_TOURNAMENT.state().active?.pending==='next');await page.evaluate(()=>window.AI_SHOGI_TOURNAMENT.next());await page.waitForTimeout(180)}}await page.waitForFunction(()=>window.AI_SHOGI_TOURNAMENT_BOSS.audit().bossStatus==='pending');const state=await page.evaluate(()=>window.AI_SHOGI_TOURNAMENT.state().active),audit=await page.evaluate(()=>window.AI_SHOGI_TOURNAMENT_BRACKET_UI.audit()),finalSkin=await page.evaluate(()=>window.AI_SHOGI_TOURNAMENT_SKIN.audit());assert.equal(state.status,'boss_pending');assert.equal(state.bracket.rounds[4][0],'__PLAYER__');assert.equal((await page.evaluate(()=>window.AI_SHOGI_TOURNAMENT_BOSS.audit())).bossInBracket,false);assert.equal(audit.alignmentErrors,0);assert.equal(finalSkin.connectors,30);console.log('PASS_TOURNAMENT21546A_INTEGRATED_BRACKET '+JSON.stringify({connectors:audit.connectors,pairingErrors:audit.pairingErrors,invalidWins:audit.invalidWins,maxAlignmentError:audit.maxAlignmentError,openingMaxAlignmentError:opening.max,bossInBracket:false,tournamentChampion:'player',next:'boss'}));await page.close()}finally{await browser.close();await new Promise(r=>server.close(r))}